import math
import time


class TreeNode:

    def __init__(self, board, player):
        self.board = board
        self.player = player
        self.score = 0
        self.children = []
        self.best_child = None
        self.winner, self.gameover = self.check_win()

    def add_child(self, child):
        self.children.append(child)

    def __repr__(self):
        return str(self)

    def __str__(self):
        x = "   0   1   2\n"
        for i in range(len(self.board)):
            x += f"{i} "
            for j in range(len(self.board[i])):
                if j == 0 or j == 1:
                    x += f" {self.board[i][j]} |"
                else:
                    x += f" {self.board[i][j]} "
            if i == 0 or i == 1:
                x += f"\n  ---+---+---\n"
        return x

    def check_win(self):
        # check each row for a winner
        if (
            self.board[0][0] == self.board[0][1] == self.board[0][2]
            and self.board[0][0] != ' '
        ):
            return self.board[0][0], True
        elif (
            self.board[1][0] == self.board[1][1] == self.board[1][2]
            and self.board[1][0] != ' '
        ):
            return self.board[1][0], True
        elif (
            self.board[2][0] == self.board[2][1] == self.board[2][2]
            and self.board[2][0] != ' '
        ):
            return self.board[2][0], True

        # check each column for a winner
        if (
            self.board[0][0] == self.board[1][0] == self.board[2][0]
            and self.board[0][0] != ' '
        ):
            return self.board[0][0], True
        elif (
            self.board[0][1] == self.board[1][1] == self.board[2][1]
            and self.board[0][1] != ' '
        ):
            return self.board[0][1], True
        elif (
            self.board[0][2] == self.board[1][2] == self.board[2][2]
            and self.board[0][2] != ' '
        ):
            return self.board[0][2], True

        # check each diagonal for a winner
        if (
            self.board[0][0] == self.board[1][1] == self.board[2][2]
            and self.board[0][0] != ' '
        ):
            return self.board[0][0], True
        elif (
            self.board[0][2] == self.board[1][1] == self.board[2][0]
            and self.board[0][2] != ' '
        ):
            return self.board[0][2], True

        # check for a draw (no winners and board is full)
        for row in self.board:
            for space in row:
                if space == ' ':
                    return None, False

        # game is a draw
        return "draw", True

    def set_best_child(self):
        winner, gameover = self.winner, self.gameover
        if gameover and winner == "O":
            self.score = 10
            self.best_child = None
            return

        elif gameover and winner == "X":
            self.score = -10
            self.best_child = None
            return

        elif winner == "draw":
            self.score = 0
            self.best_child = None
            return

        for child in self.children:
            child.set_best_child()

        best_child = None
        if self.player == "O":
            best_score = -math.inf
            for child in self.children:
                if child.score > best_score:
                    best_score = child.score
                    best_child = child
        elif self.player == "X":
            best_score = math.inf
            for child in self.children:
                if child.score < best_score:
                    best_score = child.score
                    best_child = child

        self.best_child = best_child
        self.score = best_score


class Tree:

    def __init__(self, rootNode):
        self.root = rootNode
        self.nodes = {}

        t0 = time.time()
        self.build_tree(self.root)
        print("Built Tree:", time.time() - t0)

        t1 = time.time()
        self.root.set_best_child()
        print("Best Child:", time.time() - t1)
        print("Total Time:", time.time() - t0)

    def copy_board(self, board):
        new_board = []
        for i in range(len(board)):
            row = []
            for j in range(len(board[i])):
                row.append(board[i][j])
            new_board.append(row)
        return new_board

    def build_tree(self, node):
        if node.gameover:
            return

        child_player = ""
        if node.player == "X":
            child_player = "O"
        else:
            child_player = "X"

        for i in range(len(node.board)):
            for j in range(len(node.board[i])):
                if node.board[i][j] == ' ':
                    copy = self.copy_board(node.board)
                    copy[i][j] = node.player
                    child = TreeNode(copy, child_player)
                    # NEW: check if this node has already been created
                    if str(child) not in self.nodes:
                        # doesn't exist
                        self.nodes[str(child)] = child
                        node.add_child(child)
                        self.build_tree(child)
                    else:
                        # does exist
                        node.add_child(self.nodes[str(child)])

    def play_game(self):
        print("\nWelcome to Tic-Tac-Toe AI!")
        input("Press Enter to Start!")
        curr = self.root
        print()
        print(curr)

        while True:
            print()
            print("It is now your turn.")

            while True:
                row = int(input("Which row would you like to place your X? "))
                col = int(
                    input("Which column would you like to place your X? ")
                )
                if (
                    row < 0
                    or row > 2
                    or col < 0
                    or col > 2
                    or curr.board[row][col] != ' '
                ):
                    print(
                        "Your row and column values are invalid. Please enter them again."
                    )
                else:
                    break

            for child in curr.children:
                if child.board[row][col] == curr.player:
                    curr = child
                    break

            print()
            print(curr)
            winner, gameover = curr.check_win()
            if gameover:
                break

            print()
            print("Now it's the AI's turn!")
            time.sleep(1)
            curr = curr.best_child
            print()
            print(curr)
            winner, gameover = curr.check_win()
            if gameover:
                break

        print()
        if winner == "draw":
            print("Game Over! It was a draw!")
        elif winner == "X":
            print("Game over! You won!")
        else:
            print("Game over! The AI has won!")


