        if coordforspace[0] + 1 < 3:
            neighbors_grid = copy.deepcopy(self.board)

            neighbors_grid[coordforspace[0]][coordforspace[1]] = neighbors_grid[
                coordforspace[0] + 1
            ][coordforspace[1]]
            neighbors_grid[coordforspace[0] + 1][coordforspace[1]] = " "

            node1 = Node(neighbors_grid)
            # print("down")
