    # solve puzzle with A* Search
    def a_star_solve(self):
        if not self.start_node.is_solvable():
            return None
        frontier = PriorityQueue()
        frontier.put((self.start_node.get_heuristic(), 0, self.start_node,
                      [self.start_node]))
